from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 330, "תרשים א: שני גופים במסה M תלויים משני צדי גלגלת בחוט b, והגלגלת תלויה מהתקרה בחוט c. תרשים ב: לגוף הימני נוסף גוף במסה m בחוט d")
    for ox, extra, lab in ((140, False, "תרשים א"), (400, True, "תרשים ב")):
        g.ceiling(ox - 60, ox + 60, 20)
        g.line(ox, 20, ox, 70, width=1.5); g.text(ox + 8, 50, "c", anchor="start")
        g.pulley(ox, 90, 22)
        g.line(ox - 22, 90, ox - 22, 190, width=1.5); g.line(ox + 22, 90, ox + 22, 190, width=1.5)
        g.text(ox + 30, 150, "b", anchor="start")
        g.block(ox - 22, 205, 34, 30, "M"); g.block(ox + 22, 205, 34, 30, "M")
        if extra:
            g.line(ox + 22, 220, ox + 22, 270, width=1.5); g.text(ox + 30, 250, "d", anchor="start")
            g.block(ox + 22, 284, 28, 26, "m")
        g.heb(ox, 322, lab)
    return g

def hang(forces, label, alt, note, pos=90, body="block"):
    return lambda: fbd(forces, alt, positive=pos, body=body, body_label=label, note=note)

E(id="bagrut-1993-q2", year=1993, label="1993 שאלה 2", topic="dynamics", sub="dyn-systems", diff=3, fig=fig,
  stem=r"שני גופים, כל אחד במסה $M$, קשורים זה לזה בחוט $b$ שעובר סביב גלגלת. הגלגלת תלויה מהתקרה בחוט $c$ (תרשים א). מסות החוטים זניחות, ואין חיכוך.",
  parts=[
    P("א1", r"מה המתיחות בחוט $b$, לפי נתוני השאלה?", choice([r"$T_b = Mg$", r"$T_b = 2Mg$", r"$T_b = \tfrac{1}{2}Mg$", r"$T_b = 0$"], 0), ["fbd", "principle"], [
        X(r"המסות שוות, ולכן המערכת במנוחה. בוחרים כלפי מעלה כחיובי. השאלה לא קבעה כיוון."),
        D(r"תרשים הכוחות על כל אחד מהגופים", hang([("T_b", 90, 1.0), ("Mg", -90, 1.0)], "M", "תרשים כוחות על גוף: מתיחות החוט b כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה", "במנוחה")),
        S(r"משוואת כוחות לגוף", r"בכיוון החיובי פועלת המתיחות, ונגדה הכובד. אין תאוצה", r"T_b - Mg = 0 \;\Rightarrow\; T_b = Mg", eq=r"\Sigma\vec F = m\vec a"),
    ], r"$T_b = Mg$", key=r"Mg"),
    P("א2", r"מה המתיחות בחוט $c$?", choice([r"$T_c = 2Mg$", r"$T_c = Mg$", r"$T_c = 4Mg$", r"$T_c = \tfrac{1}{2}Mg$"], 0), ["fbd", "principle"], [
        D(r"תרשים הכוחות על הגלגלת", hang([("T_c", 90, 1.2), ("T_b", -90, 0.7, -14), ("T_b", -90, 0.7, 14)], None, "תרשים כוחות על הגלגלת: מתיחות החוט c כלפי מעלה, ושני הצדדים של החוט b כלפי מטה. הכיוון החיובי כלפי מעלה", "הגלגלת קלה", body="ball")),
        S(r"משוואת כוחות לגלגלת", r"הגלגלת קלה ובמנוחה. בכיוון החיובי פועל החוט שמחזיק אותה, ונגדו שני הצדדים של החוט שכרוך עליה", r"T_c - 2T_b = 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים", r"את המתיחות מסעיף הקודם", r"T_c = 2Mg"),
    ], r"$T_c = 2Mg$", key=r"2Mg"),
    P("ב1", r"תולים על הגוף הימני גוף נוסף שמסתו $m$, בחוט קל $d$ (תרשים ב). הראו שהתאוצה $a$ של הגוף שמסתו $m$ קטנה מתאוצת הנפילה החופשית $g$.", OPEN, ["fbd", "principle", "algebra"], [
        X(r"הצד הימני כבד יותר, ולכן הוא יורד והצד השמאלי עולה. בוחרים לכל גוף את כיוון התנועה שלו כחיובי: בצד ימין כלפי מטה, ובצד שמאל כלפי מעלה. כך לכל הגופים אותה תאוצה, עם אותו סימן."),
        D(r"תרשים הכוחות על הגוף השמאלי", hang([("T_b", 90, 1.05), ("Mg", -90, 1.0)], "M", "תרשים כוחות על הגוף השמאלי: מתיחות החוט b כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה", "עולה")),
        D(r"תרשים הכוחות על הגוף הימני", hang([("T_b", 90, 1.05), ("Mg", -90, 1.0, -12), ("T_d", -90, 0.5, 12)], "M", "תרשים כוחות על הגוף הימני: מתיחות החוט b כלפי מעלה, וכלפי מטה כוח הכובד ומתיחות החוט d. הכיוון החיובי כלפי מטה", "יורד", pos=-90)),
        D(r"תרשים הכוחות על הגוף התחתון", hang([("T_d", 90, 0.5), ("mg", -90, 0.6)], "m", "תרשים כוחות על הגוף התחתון: מתיחות החוט d כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מטה", "יורד", pos=-90)),
        S(r"משוואות הכוחות", r"לכל גוף: הכוחות בכיוון החיובי שלו, פחות הכוחות נגדו", r"T_b - Mg = Ma \qquad Mg + T_d - T_b = Ma \qquad mg - T_d = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחברים את שלוש המשוואות", r"המתיחויות הפנימיות מתבטלות", r"mg = (2M + m)\,a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"מחלקים במסה הכוללת", r"a = \frac{m}{2M + m}\,g"),
        S(r"משווים לתאוצת הכובד", r"המונה קטן מהמכנה, ולכן השבר קטן מאחד", r"\frac{m}{2M + m} < 1 \;\Rightarrow\; a < g"),
    ], r"$a = \frac{m}{2M + m}g$, והמכנה גדול מהמונה"),
    P("ב2", r"אדם במעלית, שיורדת במהירות קבועה, מסתכל דרך חלון על הגוף שמסתו $m$. האם התאוצה של הגוף, כפי שהאדם רואה אותה, קטנה מהתאוצה $a$ ביחס לארץ, גדולה ממנה או שווה לה?", choice(["קטנה", "גדולה", "שווה"], 2), ["principle"], [
        S(r"תאוצה יחסית", r"מחסירים את התאוצה של המעלית. למעלית שנעה במהירות קבועה אין תאוצה", r"a' = a - 0 = a"),
    ], r"שווה", key=r"אותה תאוצה"),
    P("ג", r"ברגע מסוים החוט $d$ נקרע. איזו תנועה עושה הגוף הימני (שמסתו $M$) אחרי הקריעה: במהירות קבועה, בתאוצה קבועה, או אחרת? הסבירו.", choice(["מהירות קבועה", "תאוצה קבועה", "אחרת"], 0), ["fbd", "principle"], [
        D(r"אחרי הקריעה: תרשים הכוחות על הגוף הימני", hang([("T_b", 90, 1.0), ("Mg", -90, 1.0)], "M", "תרשים כוחות על הגוף הימני אחרי הקריעה: מתיחות החוט b כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מטה", "החוט d נקרע", pos=-90)),
        S(r"משוואות הכוחות אחרי הקריעה", r"נשארו שני גופים שווים משני צדי הגלגלת. מחברים את המשוואות, והמתיחות מתבטלת", r"T_b - Mg = Ma,\quad Mg - T_b = Ma \;\Rightarrow\; 0 = 2Ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מסקנה", r"אין תאוצה, ולכן המערכת ממשיכה במהירות שהייתה לה ברגע הקריעה", r"a = 0 \;\Rightarrow\; \Delta v = 0"),
    ], r"במהירות קבועה: המערכת מאוזנת, והיא ממשיכה במהירות של רגע הקריעה"),
  ],
  concepts=["גלגלת", "מתיחות בחוטים", "מערכת גופים", "תאוצה יחסית", "מערכת מאוזנת בתנועה"],
  summary=r"מכונת אטווד: מתיחויות בשיווי משקל, תאוצה כשמוסיפים גוף, ומה קורה כשהגוף הנוסף נופל.",
  review="הנחה שלי.\nבמקור יש סעיפים א(1), א(2), ב(1), ב(2), וכך גם אצלנו. בסעיפי הביטויים התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
